          explanation: 'Relative pronouns look like the definite article. Only the dative plural (denen) and the genitive (dessen, deren) are different. The relative clause usually follows the noun directly, is separated by commas, and ends with the conjugated verb.',
          examples: [
            { de: 'Nominativ: der – die – das – die (Pl.)', en: 'nominative: masc. – fem. – neut. – plural' },
            { de: 'Akkusativ: den – die – das – die (Pl.)', en: 'accusative' },
            { de: 'Dativ: dem – der – dem – denen (Pl.)', en: 'dative' },
            { de: 'Genitiv: dessen – deren – dessen – deren (Pl.)', en: 'genitive (whose)' },
            { de: 'Der Mann, der dort steht, ist mein Onkel.', en: 'The man who is standing there is my uncle.' },
          ],
